def variant(names, extra=()):
    d = "/tmp/var_" + "_".join(names)
    shutil.rmtree(d, ignore_errors=True)
    shutil.copytree("/app/quayside", d + "/quayside")
    for n in names:
        f, a, b = FIXES[n]
        p = os.path.join(d, f)
        s = open(p).read()
        assert a in s, n
        open(p, "w").write(s.replace(a, b))
    return d

def run(d, since="2027-06-08T14:00:05.000Z"):
    out = subprocess.run(["python3", "/app/tools/replay.py", "--pkg", d, "--since", since, "--diff"], capture_output=True, text=True).stdout
    return out

if __name__ == "__main__":
    names = sys.argv[1:]
    d = variant(names)
    out = run(d)
    lines = [l for l in out.splitlines() if not l.startswith("#")]
    print(out.splitlines()[-1])
    fixed = [l for l in lines if "logged=dead-letter" in l and "replay=dead-letter" not in l]
    new = [l for l in lines if "logged=dead-letter" not in l or "replay=dead-letter" in l]
    print("avoided", len(fixed), "other diffs", len(new))
    for l in fixed[:3]: print(l)
    for l in new[:5]: print(l)

